-- SANDBOX/DEMO ONLY. Live course/access/transport checks; all changes roll back.
begin;
set local statement_timeout='25s';
create function pg_temp.course_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Sick course QA: %',label;end if;end$$;
do $$declare s jsonb;c uuid;u uuid;member uuid;e uuid;cid uuid;r jsonb;fingerprint text;begin
 select payload into s from public.demo_sandbox_snapshots where snapshot_key='sick-leave-course-v1';
 c:=(s->>'company_id')::uuid;u:=(s->>'user_id')::uuid;e:=(s->>'employee_id')::uuid;cid:=(s->>'case_id')::uuid;
 select user_id into member from hr_private.employees where id=e and company_id=c;
 select md5(jsonb_agg(to_jsonb(cv) order by cv.id)::text) into fingerprint from hr_private.sick_leave_cases cv;
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform pg_temp.course_assert((public.demo_sandbox_preflight()->>'ok')::boolean,'existing infrastructure preflight');
 r:=public.demo_kshms_hr_course_preflight();
 perform pg_temp.course_assert((r->>'ok')::boolean and jsonb_array_length(r->'checks')=5,'all five course checks');
 perform pg_temp.course_assert(not exists(select 1 from jsonb_array_elements(r->'checks') x where not(x->>'ok')::boolean),'every returned course point green');
 r:=public.hr_sick_leave_get(c,e,cid);
 perform pg_temp.course_assert(r#>>'{conversation,stage}'='meeting' and r#>>'{permissions,meeting}'='true','leader opens unconfirmed shared plan');
 perform pg_temp.course_assert(r#>>'{conversation,confirmations,leader}' is null and r#>>'{conversation,confirmations,employee}' is null,'no seeded confirmations');
 perform pg_temp.course_assert(jsonb_array_length(r#>'{conversation,sharing,nav}')=0 and jsonb_array_length(r#>'{conversation,sharing,sykmelder}')=0,'no seeded submissions');
 perform pg_temp.course_assert(jsonb_array_length(r#>'{conversation,actions}')=1 and r#>>'{conversation,actions,0,done}'='false','one open synthetic action');
 perform pg_temp.course_assert((select count(*)=4 from hr_private.sick_leave_tasks(c,cid) where recipient_id=u and task_key in('plan','meeting1','activity','meeting2')),'all four milestone tasks reach leader');
 perform set_config('request.jwt.claim.sub',member::text,true);
 r:=public.hr_sick_leave_get(c,e,cid);
 perform pg_temp.course_assert(r#>>'{conversation,shared}'='true' and r#>>'{permissions,meeting}'='false','employee reads shared plan without leader edit permission');
 perform pg_temp.course_assert((select count(*)=1 from hr_private.sick_leave_tasks(c,cid) where recipient_id=member and task_key like 'action:%'),'employee gets only their action');
 perform set_config('request.jwt.claim.sub',u::text,true);
 update hr_private.followup_settings set enabled=true where singleton;
 perform pg_temp.course_assert(not(public.demo_kshms_hr_course_preflight()->>'ok')::boolean,'enabled HR reminder mail blocks course');
 update hr_private.followup_settings set enabled=false where singleton;
 update hr_private.employees set leader_id=null where id=e;
 r:=public.demo_kshms_hr_course_preflight();
 perform pg_temp.course_assert(not(r->>'ok')::boolean and exists(select 1 from jsonb_array_elements(r->'checks') x where x->>'key'='course_sick_leave' and not(x->>'ok')::boolean),'wrong current leader blocks sick-leave course');
 update hr_private.employees set leader_id=u where id=e;
 perform pg_temp.course_assert((public.demo_kshms_hr_course_preflight()->>'ok')::boolean,'preflight restored');
 perform public.demo_kshms_hr_course_reset();
 perform pg_temp.course_assert((select md5(jsonb_agg(to_jsonb(cv) order by cv.id)::text)=fingerprint from hr_private.sick_leave_cases cv),'course reset preserves personal case history');
 perform pg_temp.course_assert((public.demo_kshms_hr_course_preflight()->>'ok')::boolean,'reset retains ready sick-leave example');
 perform pg_temp.course_assert(not exists(select 1 from hr_private.followup_deliveries),'no reminder deliveries or email test');
end$$;
select 'PASS: five course checks, current roles, four milestones, unconfirmed plan, no submissions, transport guard, reset preserves case history; rollback' as result;
rollback;
